import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            s = next(iterator)
        except StopIteration:
            break

        if len(s) != n:
            pass

        v_indices = [i for i, c in enumerate(s) if c == 'V']
        k_indices = [i for i, c in enumerate(s) if c == '?']

        bad_shifts = set()

        for d in range(1, n + 1):
            conflict = False

            if d > n // 2:
                pass

            for i in v_indices:
                if i + d < n:
                    c2 = s[i + d]
                    if c2 == 'K':
                        conflict = True
                        break
                    elif c2 == '?':
                        pass

            if conflict:
                bad_shifts.add(d)
                continue

            for i in k_indices:
                if i + d < n:
                    c1 = s[i]
                    c2 = s[i + d]

                    if c1 == 'V' and c2 == 'K':
                        conflict = True
                        break
            if conflict:
                bad_shifts.add(d)
                continue

            if not conflict:
                pass

        possible_periods = []
        for d in range(1, n + 1):
            if d in bad_shifts:
                continue

            ok = True
            for i in range(n - d):
                c1 = s[i]
                c2 = s[i + d]

                if c1 == '?' and c2 == '?':
                    continue
                if c1 == '?' or c2 == '?':
                    continue
                if c1 != c2:
                    ok = False
                    break

            if ok:
                possible_periods.append(d)

        results.append(str(len(possible_periods)))
        results.append(" ".join(map(str, possible_periods)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
